package main

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"time"
)

// planComment is written into every plan file. The file is the whole safety
// mechanism, so it has to explain itself to someone who did not read the
// README.
var planComment = []string{
	"Generated by hcloud-pricetag. NOTHING is written to Hetzner until you set",
	"\"confirmed\": true on an entry and then run: hcloud-pricetag apply",
	"",
	"Confirm ONLY servers you know were never rescaled or otherwise modified",
	"since they were created. Those keep their pre-adjustment price. Servers",
	"that were rescaled pay the new price, and the Hetzner API does not record",
	"that this happened — so this tool cannot check it for you. Being created",
	"before the cutoff is necessary evidence, not sufficient evidence, and that",
	"gap is exactly why there is no flag to confirm everything at once.",
	"",
	"Removing an entry is the same as leaving it unconfirmed.",
}

// PlanEntry is one proposed change.
type PlanEntry struct {
	ID         int64     `json:"id"`
	Name       string    `json:"name"`
	ServerType string    `json:"server_type"`
	Location   string    `json:"location"`
	Created    time.Time `json:"created"`
	// Informational: what Hetzner charges now vs. what the entry would claim.
	CurrentListEURMonth string `json:"current_list_eur_month"`
	ProposedEURMonth    string `json:"proposed_eur_month"`
	ProposedEURHour     string `json:"proposed_eur_hour"`
	// Labels is what would be merged into the server's existing labels.
	Labels    map[string]string `json:"labels"`
	Confirmed bool              `json:"confirmed"`
}

// SkippedServer records a server the plan deliberately does not propose, and
// why. Silence here would read as "covered everything".
type SkippedServer struct {
	ID         int64  `json:"id"`
	Name       string `json:"name"`
	ServerType string `json:"server_type,omitempty"`
	Location   string `json:"location,omitempty"`
	Reason     string `json:"reason"`
}

// Plan is the reviewable artifact between reading and writing.
type Plan struct {
	Comment        []string        `json:"_comment"`
	PriceTable     string          `json:"price_table_source"`
	Cutoff         time.Time       `json:"cutoff"`
	Servers        []PlanEntry     `json:"servers"`
	Skipped        []SkippedServer `json:"skipped"`
	TotalInspected int             `json:"total_inspected"`
}

// BuildPlan proposes an override for every server that predates the cutoff and
// has a pre-adjustment price in the table. Everything else lands in Skipped
// with a reason.
func BuildPlan(servers []Server, table *Table, cutoff time.Time) Plan {
	p := Plan{
		Comment:        planComment,
		PriceTable:     table.Source,
		Cutoff:         cutoff.UTC(),
		TotalInspected: len(servers),
	}
	for _, s := range servers {
		// Strictly before: the adjustment applies from the cutoff onwards.
		if !s.Created.Before(cutoff) {
			p.Skipped = append(p.Skipped, SkippedServer{
				ID: s.ID, Name: s.Name, ServerType: s.Type, Location: s.Location,
				Reason: "created at or after the cutoff — already on current pricing",
			})
			continue
		}
		entry, found := table.Lookup(s.Type, s.Location)
		if !found {
			// Either the type's price did not change, or the table predates
			// it. Guessing here would be worse than saying so.
			p.Skipped = append(p.Skipped, SkippedServer{
				ID: s.ID, Name: s.Name, ServerType: s.Type, Location: s.Location,
				Reason: fmt.Sprintf("no pre-adjustment price for %s in %s in this table", s.Type, s.Location),
			})
			continue
		}
		want := entry.Labels()
		if labelsAlreadySet(s.Labels, want) {
			p.Skipped = append(p.Skipped, SkippedServer{
				ID: s.ID, Name: s.Name, ServerType: s.Type, Location: s.Location,
				Reason: "already carries exactly this override",
			})
			continue
		}
		p.Servers = append(p.Servers, PlanEntry{
			ID: s.ID, Name: s.Name, ServerType: s.Type, Location: s.Location,
			Created:             s.Created.UTC(),
			CurrentListEURMonth: EURMonth(entry.New.MonthlyNetCents),
			ProposedEURMonth:    EURMonth(entry.Old.MonthlyNetCents),
			ProposedEURHour:     EURHour(entry.Old.HourlyNetMilliCents),
			Labels:              want,
			Confirmed:           false,
		})
	}
	sort.Slice(p.Servers, func(i, j int) bool { return p.Servers[i].ID < p.Servers[j].ID })
	sort.Slice(p.Skipped, func(i, j int) bool { return p.Skipped[i].ID < p.Skipped[j].ID })
	return p
}

func labelsAlreadySet(have, want map[string]string) bool {
	for k, v := range want {
		if have[k] != v {
			return false
		}
	}
	return true
}

// Drift explains why a live server no longer matches what was planned, or
// returns "" when it still does.
//
// This is the check an interactive prompt could not offer. A rescale between
// plan and apply is precisely the event that forfeits the old price, and it
// shows up here as a changed server type.
func (e PlanEntry) Drift(s Server) string {
	if s.Type != e.ServerType {
		return fmt.Sprintf("server type is %q now, was %q when planned — a rescale forfeits the old price", s.Type, e.ServerType)
	}
	if s.Location != e.Location {
		return fmt.Sprintf("location is %q now, was %q when planned", s.Location, e.Location)
	}
	if !s.Created.UTC().Equal(e.Created.UTC()) {
		return fmt.Sprintf("created timestamp is %s now, was %s when planned — this is not the same server",
			s.Created.UTC().Format(time.RFC3339), e.Created.UTC().Format(time.RFC3339))
	}
	return ""
}

// MergeLabels returns the server's labels with the entry's overrides applied.
// Foreign labels are preserved: PUT /servers/{id} replaces the whole map.
func (e PlanEntry) MergeLabels(current map[string]string) map[string]string {
	out := make(map[string]string, len(current)+len(e.Labels))
	for k, v := range current {
		out[k] = v
	}
	for k, v := range e.Labels {
		out[k] = v
	}
	return out
}

// StripOverrides returns labels with both reserved keys removed.
func StripOverrides(current map[string]string) (map[string]string, bool) {
	out := make(map[string]string, len(current))
	changed := false
	for k, v := range current {
		if k == LabelMonthly || k == LabelHourly {
			changed = true
			continue
		}
		out[k] = v
	}
	return out, changed
}

func (p Plan) Save(path string) error {
	raw, err := json.MarshalIndent(p, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, append(raw, '\n'), 0o644)
}

func LoadPlan(path string) (*Plan, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read plan: %w", err)
	}
	var p Plan
	if err := json.Unmarshal(raw, &p); err != nil {
		return nil, fmt.Errorf("parse plan: %w", err)
	}
	return &p, nil
}

// labelWriter is the slice of Client that applying needs, so the logic is
// testable without a network.
type labelWriter interface {
	SetLabels(ctx context.Context, id int64, labels map[string]string) error
}

// ApplyResult reports one entry's outcome.
type ApplyResult struct {
	Entry   PlanEntry
	Written bool
	Skipped string // reason, when not written
}

// Apply writes the confirmed entries, refusing any whose live server drifted
// from what was planned.
func Apply(ctx context.Context, w labelWriter, p *Plan, live []Server, dryRun bool) ([]ApplyResult, error) {
	byID := make(map[int64]Server, len(live))
	for _, s := range live {
		byID[s.ID] = s
	}
	var results []ApplyResult
	for _, e := range p.Servers {
		if !e.Confirmed {
			results = append(results, ApplyResult{Entry: e, Skipped: "not confirmed"})
			continue
		}
		s, ok := byID[e.ID]
		if !ok {
			results = append(results, ApplyResult{Entry: e, Skipped: "server no longer exists"})
			continue
		}
		if drift := e.Drift(s); drift != "" {
			results = append(results, ApplyResult{Entry: e, Skipped: drift})
			continue
		}
		merged := e.MergeLabels(s.Labels)
		if labelsAlreadySet(s.Labels, e.Labels) {
			results = append(results, ApplyResult{Entry: e, Skipped: "already up to date"})
			continue
		}
		if !dryRun {
			if err := w.SetLabels(ctx, e.ID, merged); err != nil {
				return results, fmt.Errorf("server %d (%s): %w", e.ID, e.Name, err)
			}
		}
		results = append(results, ApplyResult{Entry: e, Written: true})
	}
	return results, nil
}
